mapper.select:
select 
from expert_risk_review r
left join expert_profile p on p.user_id = r.expert_user_id
where r.source_event_id = #{sourceEventId}
  and r.risk_type = #{riskType}
limit 1

select from expert_risk_review r left join expert_profile p on p.user_id = r.expert_user_id
r.status = #{status}
order by r.create_time desc, r.risk_id desc
